"""Standalone job scraper for cognizant.com (India roles). Generated by the agent; runs with NO LLM calls.
Run:  python scraper.py [output.jsonl]
source_type=html_ssr, pagination=page_number.
"""

import json
import os
import sys
import time
import html as html_lib
from datetime import datetime
from urllib.parse import urljoin, urlparse, parse_qs, urlencode, urlunparse

import requests
from bs4 import BeautifulSoup

HEADERS = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
    "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    "Accept-Language": "en-US,en;q=0.9",
}

BASE_URL = "https://careers.cognizant.com/india-en/jobs/?page=1#results"


def parse_html(text):
    if isinstance(text, bytes):
        text = text.decode("utf-8", errors="replace")
    text = text or ""
    soup = BeautifulSoup(text, "lxml")
    for tag in ("input", "script", "a"):
        raw_count = text.count("<" + tag)
        if raw_count >= 2 and len(soup.find_all(tag)) < raw_count // 2:
            return BeautifulSoup(text, "html.parser")
    return soup


_INDIA_CITY_FALLBACK = {
    "bengaluru": "Bengaluru", "bangalore": "Bangalore", "mumbai": "Mumbai", "delhi": "Delhi",
    "new delhi": "New Delhi", "gurugram": "Gurugram", "gurgaon": "Gurgaon", "noida": "Noida",
    "hyderabad": "Hyderabad", "chennai": "Chennai", "pune": "Pune", "kolkata": "Kolkata",
    "ahmedabad": "Ahmedabad",
}


def resolve_location(location_raw):
    # returns (city, state, country, country_code) -- all None if unresolvable, never guessed.
    if not location_raw:
        return (None, None, None, None)
    first_segment = location_raw.split(";")[0].strip()  # some platforms join multiple locations with ';'
    parts = [p.strip() for p in first_segment.split(",")]
    if len(parts) >= 2:
        # explicit "City, [State,] Country" format -- last segment is the country
        city = parts[0] or None
        state = parts[1] if len(parts) >= 3 else None
        country_raw = parts[-1]
        if country_raw.lower() in ("india", "in"):
            return (city, state, "India", "IN")
        return (city, state, country_raw or None, None)
    # no comma: bare city name -- only resolve via the small generic fallback dict, never guess otherwise
    bare = first_segment.lower()
    if bare in _INDIA_CITY_FALLBACK:
        return (_INDIA_CITY_FALLBACK[bare], None, "India", "IN")
    return (None, None, None, None)


def collect_job_links(soup, page_url):
    urls = []
    for a in soup.find_all("a", href=True):
        h = a["href"]
        tail = h.rstrip("/").split("/")[-1]
        if any(k in h.lower() for k in ("/job/", "/jobs/", "/position/", "/vacancy/", "/opening/")) \
                or (tail.isdigit() and len(tail) >= 6):
            u = urljoin(page_url, h)
            if u not in urls:
                urls.append(u)
    return urls


def ldjson_objects(soup):
    objs = []
    for tag in soup.find_all("script", type="application/ld+json"):
        try:
            data = json.loads(tag.string or "")
        except (json.JSONDecodeError, TypeError):
            continue
        items = data if isinstance(data, list) else [data]
        for it in items:
            if isinstance(it, dict):
                objs.append(it)
                if isinstance(it.get("@graph"), list):
                    objs.extend(x for x in it["@graph"] if isinstance(x, dict))
    return objs


def ldjson_get(soup, *keys):
    for o in ldjson_objects(soup):
        for k in keys:
            if o.get(k):
                return o[k]
    return None


def ldjson_location(soup):
    for o in ldjson_objects(soup):
        if o.get("@type") == "JobPosting" and o.get("jobLocation"):
            locs = o["jobLocation"] if isinstance(o["jobLocation"], list) else [o["jobLocation"]]
            for l in locs:
                addr = (l or {}).get("address") or {}
                if isinstance(addr, dict) and (addr.get("addressLocality") or addr.get("addressCountry")):
                    city = addr.get("addressLocality") or None
                    state = addr.get("addressRegion") or None
                    country_raw = str(addr.get("addressCountry") or "").strip()
                    if country_raw.upper() in ("IN", "IND", "INDIA"):
                        return (city, state, "India", "IN")
                    return (city, state, country_raw or None, None)
    return None


def find_structural_location(container):
    if container is None:
        return None
    for el in container.find_all(["span", "div", "p", "li", "td", "h1", "h2", "h3"]):
        text = el.get_text(" ", strip=True)
        if not text or len(text) > 100:
            continue
        candidate = text.split(":", 1)[-1].strip() if ":" in text else text
        _, _, country, _ = resolve_location(candidate)
        if country:
            return candidate
    return None


def sel_text(soup, css):
    el = soup.select_one(css)
    return el.get_text(" ", strip=True) if el else None


def fetch_with_retries(url, headers, timeout=30):
    session = requests.Session()
    last_resp = None
    for attempt in range(4):
        try:
            resp = session.get(url, headers=headers, timeout=timeout)
            last_resp = resp
            if resp.status_code in (429, 500, 502, 503, 504, 403):
                if attempt < 3:
                    time.sleep(2 ** attempt)
                    continue
            return resp
        except requests.RequestException:
            if attempt < 3:
                time.sleep(2 ** attempt)
                continue
    return last_resp


def parse_date_text(text):
    if not text:
        return None
    txt = text.strip()
    fmts = [
        "%b %d %Y",
        "%b %d, %Y",
        "%Y-%m-%d",
        "%m/%d/%Y",
        "%d %b %Y",
        "%d %B %Y",
    ]
    for fmt in fmts:
        try:
            return datetime.strptime(txt, fmt).date().isoformat()
        except ValueError:
            pass
    try:
        return datetime.fromisoformat(txt).date().isoformat()
    except ValueError:
        return None


def normalize_url(u, base=None):
    if not u:
        return None
    return urljoin(base or BASE_URL, u)


def detail_job_id_from_url(u):
    if not u:
        return None
    path = urlparse(u).path.rstrip("/")
    parts = [p for p in path.split("/") if p]
    for p in reversed(parts):
        if p.isdigit():
            return p
    return None


def extract_detail(page_url, session=None):
    resp = fetch_with_retries(page_url, HEADERS)
    if not resp or resp.status_code != 200:
        return None
    soup = parse_html(resp.text)
    title = ldjson_get(soup, "headline", "title", "name")
    if isinstance(title, str) and " | " in title:
        title = title.split(" | ", 1)[0].strip()
    if title:
        title = html_lib.unescape(title.strip())
    else:
        title = sel_text(soup, "h1.hero-heading")
        title = html_lib.unescape(title.strip()) if title else None

    job_id = ldjson_get(soup, "identifier")
    if isinstance(job_id, dict):
        job_id = job_id.get("value") or job_id.get("name")
    if not job_id:
        job_id = sel_text(soup, ".hero-eyebrow")
    if not job_id:
        job_id = detail_job_id_from_url(page_url)
    if job_id:
        job_id = str(job_id).strip()

    location_raw = None
    loc = ldjson_location(soup)
    if loc is None:
        container = soup.select_one("main") or soup
        location_raw = find_structural_location(container)
        if location_raw is None:
            location_raw = sel_text(soup, ".job-meta-location strong")
            if location_raw:
                location_raw = html_lib.unescape(location_raw)
    else:
        location_raw = None

    if loc is None:
        city, state, country, country_code = resolve_location(location_raw)
    else:
        city, state, country, country_code = loc

    if country_code != "IN":
        return None

    date_text = ldjson_get(soup, "datePublished", "datePosted")
    if not date_text:
        date_text = sel_text(soup, ".job-meta-item strong")
    date_posted_text = html_lib.unescape(date_text) if date_text else None
    date_posted = parse_date_text(date_posted_text) if date_posted_text else None

    desc = ldjson_get(soup, "description")
    if not desc:
        blocks = []
        for el in soup.select("article.cms-content, .cms-content, .job-detail, main article, article"):
            txt = el.get_text(" ", strip=True)
            if txt and not txt.startswith("Location:"):
                blocks.append((len(txt), el))
        if blocks:
            desc = max(blocks, key=lambda x: x[0])[1].decode_contents()
    if desc:
        desc = html_lib.unescape(desc)

    employment_type = ldjson_get(soup, "employmentType")
    if employment_type:
        employment_type = html_lib.unescape(str(employment_type))
    work_type = sel_text(soup, ".job-meta-item a[href*='pattern=']")
    if work_type:
        work_type = html_lib.unescape(work_type)

    apply_url = None
    a = soup.select_one("a.js-apply-now[href]")
    if a:
        apply_url = normalize_url(a.get("href"), page_url)

    return {
        "title": title,
        "job_id": job_id,
        "location": {"city": city, "state": state, "country": country, "country_code": country_code},
        "url": normalize_url(page_url),
        "apply_url": apply_url,
        "date_posted": date_posted,
        "date_posted_text": date_posted_text,
        "job_description": desc,
        "employment_type": employment_type,
        "work_type": work_type,
        "salary_range": None,
    }


def write_jsonl(path, rows):
    with open(path, "w", encoding="utf-8") as f:
        for row in rows:
            f.write(json.dumps(row, ensure_ascii=False) + "\n")


def main():
    out_path = sys.argv[1] if len(sys.argv) > 1 else os.path.join(os.path.dirname(os.path.abspath(__file__)), "output.jsonl")
    rows = []
    seen = set()
    try:
        base_url = BASE_URL
        all_urls = []
        page_number = 1
        while page_number <= 120:
            page_url = f"{base_url}{'&' if '?' in base_url else '?'}page={page_number}"
            resp = fetch_with_retries(page_url, HEADERS)
            if not resp or resp.status_code != 200:
                break
            soup = parse_html(resp.text)
            links = collect_job_links(soup, page_url)
            new_links = [u for u in links if u not in all_urls]
            if not new_links:
                break
            all_urls.extend(new_links)
            page_number += 1

        if len(all_urls) > 60:
            city_slugs = ("mumbai", "bengaluru", "bangalore", "new-delhi", "delhi", "hyderabad", "pune", "chennai", "kolkata", "gurgaon", "gurugram", "noida", "ahmedabad")
            filtered = []
            skipped = 0
            for u in all_urls:
                path = urlparse(u).path.lower()
                if any(slug in path for slug in city_slugs):
                    filtered.append(u)
                else:
                    skipped += 1
            if filtered:
                print(f"prefiltered {skipped} detail URLs by city slug", file=sys.stderr)
                all_urls = filtered

        for u in all_urls:
            try:
                time.sleep(0.35)
                row = extract_detail(u)
                if not row:
                    continue
                key = row.get("job_id") or row.get("url")
                if key in seen:
                    continue
                seen.add(key)
                rows.append(row)
            except Exception as e:
                print(f"detail extraction failed for {u}: {e}", file=sys.stderr)
                continue

        write_jsonl(out_path, rows)
        return 0
    except Exception as e:
        try:
            write_jsonl(out_path, rows)
        except Exception:
            pass
        print(f"unrecoverable error: {e}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())